// GetOwnersInput holds query parameters for retrieving owners records.
// Field selection is controlled via CallOptions.FieldOptions, not this struct.
type GetOwnersInput struct {
	Filter *OwnerFilter `json:"filter"`
	Limit  *int         `json:"limit"`
	Offset *int         `json:"offset"`
	Sorts  []sql.Sort   `json:"sorts"`
	// conditions holds additional SQL conditions injected by internal callers
	// (e.g., Connection keyset conditions). Not part of the public API.
	conditions []sql.Condition
	// requiredColumns holds columns an internal caller needs read back even
	// when FieldOptions narrows the projection (e.g., Connection cursor keys).
	// Not part of the public API.
	requiredColumns []string
}

// resolveO2OJoins inspects FieldOptions and returns JOIN descriptors for each O2O relationship.
// Returns nil if no O2O relationships are requested.
func (c *ownerClient) resolveO2OJoins(d sql.Dialect, fo *OwnerFieldOptions) []sql.JoinClause {
	if fo == nil {
		return nil
	}
	var joins []sql.JoinClause
	if fo.OwnerProfile != nil {
		joins = append(joins, sql.JoinClause{
			Table: sql.Table{Schema: "", Name: "owner_profiles"},
			Alias: "o2",
			On:    fmt.Sprintf("o2.%s = o.%s", d.QuoteIdentifier("owner_id"), d.QuoteIdentifier("owner_key")),
			// The NULL-detection below reads the target's PK off the scanned
			// row, so the join carries it even when FieldOptions did not ask
			// for it — an unselected PK reads as a LEFT JOIN miss.
			Columns: unionColumns(fo.OwnerProfile.Columns(), "id"),
		})
		if fo.OwnerProfile.Owners != nil {
			joins = append(joins, sql.JoinClause{
				Table: sql.Table{Schema: "", Name: "owners"},
				Alias: "o3",
				On:    fmt.Sprintf("o3.%s = o2.%s", d.QuoteIdentifier("owner_key"), d.QuoteIdentifier("owner_id")),
				// The NULL-detection below reads the target's PK off the scanned
				// row, so the join carries it even when FieldOptions did not ask
				// for it — an unselected PK reads as a LEFT JOIN miss.
				Columns: unionColumns(fo.OwnerProfile.Owners.Columns(), "owner_key"),
			})
			if fo.OwnerProfile.Owners.OwnerProfile != nil {
				joins = append(joins, sql.JoinClause{
					Table: sql.Table{Schema: "", Name: "owner_profiles"},
					Alias: "o4",
					On:    fmt.Sprintf("o4.%s = o3.%s", d.QuoteIdentifier("owner_id"), d.QuoteIdentifier("owner_key")),
					// The NULL-detection below reads the target's PK off the scanned
					// row, so the join carries it even when FieldOptions did not ask
					// for it — an unselected PK reads as a LEFT JOIN miss.
					Columns: unionColumns(fo.OwnerProfile.Owners.OwnerProfile.Columns(), "id"),
				})
				if fo.OwnerProfile.Owners.OwnerProfile.Owners != nil {
					joins = append(joins, sql.JoinClause{
						Table: sql.Table{Schema: "", Name: "owners"},
						Alias: "o5",
						On:    fmt.Sprintf("o5.%s = o4.%s", d.QuoteIdentifier("owner_key"), d.QuoteIdentifier("owner_id")),
						// The NULL-detection below reads the target's PK off the scanned
						// row, so the join carries it even when FieldOptions did not ask
						// for it — an unselected PK reads as a LEFT JOIN miss.
						Columns: unionColumns(fo.OwnerProfile.Owners.OwnerProfile.Owners.Columns(), "owner_key"),
					})
					if fo.OwnerProfile.Owners.OwnerProfile.Owners.OwnerProfile != nil {
						joins = append(joins, sql.JoinClause{
							Table: sql.Table{Schema: "", Name: "owner_profiles"},
							Alias: "o6",
							On:    fmt.Sprintf("o6.%s = o5.%s", d.QuoteIdentifier("owner_id"), d.QuoteIdentifier("owner_key")),
							// The NULL-detection below reads the target's PK off the scanned
							// row, so the join carries it even when FieldOptions did not ask
							// for it — an unselected PK reads as a LEFT JOIN miss.
							Columns: unionColumns(fo.OwnerProfile.Owners.OwnerProfile.Owners.OwnerProfile.Columns(), "id"),
						})
						if fo.OwnerProfile.Owners.OwnerProfile.Owners.OwnerProfile.Owners != nil {
							joins = append(joins, sql.JoinClause{
								Table: sql.Table{Schema: "", Name: "owners"},
								Alias: "o7",
								On:    fmt.Sprintf("o7.%s = o6.%s", d.QuoteIdentifier("owner_key"), d.QuoteIdentifier("owner_id")),
								// The NULL-detection below reads the target's PK off the scanned
								// row, so the join carries it even when FieldOptions did not ask
								// for it — an unselected PK reads as a LEFT JOIN miss.
								Columns: unionColumns(fo.OwnerProfile.Owners.OwnerProfile.Owners.OwnerProfile.Owners.Columns(), "owner_key"),
							})
						}
					}
				}
			}
		}
	}
	return joins
}

// scanOwnersWithOneToOneJoins scans rows from a LEFT JOIN query into
// Owner entities with O2O relationships populated.
// Routes columns by alias prefix and detects LEFT JOIN misses via NULL PK detection.
func scanOwnersWithOneToOneJoins(rows database.Rows, columns []string) ([]*Owner, error) {
	var result []*Owner
	for rows.Next() {
		o := &Owner{}
		o2 := &OwnerProfile{}
		o2HasData := false
		o3 := &Owner{}
		o3HasData := false
		o4 := &OwnerProfile{}
		o4HasData := false
		o5 := &Owner{}
		o5HasData := false
		o6 := &OwnerProfile{}
		o6HasData := false
		o7 := &Owner{}
		o7HasData := false

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "o.owner_key":
				targets[idx] = &o.OwnerKey
			case "o.name":
				targets[idx] = &o.Name
			case "o2.id":
				targets[idx] = database.NullScan(&o2.ID)
				o2HasData = true
			case "o2.owner_id":
				targets[idx] = database.NullScan(&o2.OwnerID)
			case "o2.bio":
				targets[idx] = &o2.Bio
			case "o3.owner_key":
				targets[idx] = database.NullScan(&o3.OwnerKey)
				o3HasData = true
			case "o3.name":
				targets[idx] = database.NullScan(&o3.Name)
			case "o4.id":
				targets[idx] = database.NullScan(&o4.ID)
				o4HasData = true
			case "o4.owner_id":
				targets[idx] = database.NullScan(&o4.OwnerID)
			case "o4.bio":
				targets[idx] = &o4.Bio
			case "o5.owner_key":
				targets[idx] = database.NullScan(&o5.OwnerKey)
				o5HasData = true
			case "o5.name":
				targets[idx] = database.NullScan(&o5.Name)
			case "o6.id":
				targets[idx] = database.NullScan(&o6.ID)
				o6HasData = true
			case "o6.owner_id":
				targets[idx] = database.NullScan(&o6.OwnerID)
			case "o6.bio":
				targets[idx] = &o6.Bio
			case "o7.owner_key":
				targets[idx] = database.NullScan(&o7.OwnerKey)
				o7HasData = true
			case "o7.name":
				targets[idx] = database.NullScan(&o7.Name)
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan owner with joins: %w", err)
		}

		// NULL detection — assign deepest chain first, then parents
		if o7HasData && o7.OwnerKey != 0 {
			o6.Owners = o7
		} else {
			o6.Owners = nil
		}
		if o6HasData && o6.ID != 0 {
			o5.OwnerProfile = o6
		} else {
			o5.OwnerProfile = nil
		}
		if o5HasData && o5.OwnerKey != 0 {
			o4.Owners = o5
		} else {
			o4.Owners = nil
		}
		if o4HasData && o4.ID != 0 {
			o3.OwnerProfile = o4
		} else {
			o3.OwnerProfile = nil
		}
		if o3HasData && o3.OwnerKey != 0 {
			o2.Owners = o3
		} else {
			o2.Owners = nil
		}
		if o2HasData && o2.ID != 0 {
			o.OwnerProfile = o2
		} else {
			o.OwnerProfile = nil
		}

		result = append(result, o)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate owner rows: %w", err)
	}
	return result, nil
}
